
SELECT SUBSTR("T0"."CUSTOMERNAME", :p0 + 1, :p1) AS "CUT", SUBSTR("T0"."CUSTOMERNAME", :p2 + 1) AS "TAIL", (INSTR("T0"."CUSTOMERNAME", :p3, 1, 1) - 1) AS "AT", CONCAT(CONCAT("T0"."CUSTOMERNAME", :p4), "T0"."NOTE") AS "JOINED", ("T0"."NOTE" IS NULL OR TRIM("T0"."NOTE") = '') AS "BLANK" FROM "QUICKSQLORDER" "T0"
